      parseLocator: function(item) {
        if (this.opt.development_extensions.locator_date_and_revision) {
          if (item.locator) {
            item.locator = "" + item.locator;
            var idx = item.locator.indexOf("|");
            if (idx > -1) {
              var raw_locator = item.locator;
              item.locator = raw_locator.slice(0, idx);
              raw_locator = raw_locator.slice(idx + 1);
              var m2 = raw_locator.match(/^([0-9]{4}-[0-9]{2}-[0-9]{2}).*/);
              if (m2) {
                item["locator-date"] = this.fun.dateparser.parseDateToObject(m2[1]);
                raw_locator = raw_locator.slice(m2[1].length);
              }
              item["locator-extra"] = raw_locator.replace(/^\s+/, "").replace(/\s+$/, "");
            }
          }
        }
        if (item.locator) {
          item.locator = ("" + item.locator).replace(/\s+$/, "");
        }
        return item;
      },
      normalizeLocaleStr: function(str2) {
        if (!str2) {
          return;
        }
        var lst = str2.split("-");
        lst[0] = lst[0].toLowerCase();
        if (lst[1]) {
          lst[1] = lst[1].toUpperCase();
        }
        return lst.join("-");
      },
      parseNoteFieldHacks: function(Item, validFieldsForType, allowDateOverride) {
        if ("string" !== typeof Item.note) {
          return;
        }
        var elems = [];
        var lines = Item.note.split("\n");
        for (var i2 = 0, ilen = lines.length; i2 < ilen; i2++) {
          var line2 = lines[i2];
          var elems = [];
          var m2 = line2.match(CSL.NOTE_FIELDS_REGEXP);
          if (m2) {
            var splt = line2.split(CSL.NOTE_FIELDS_REGEXP);
            for (var j = 0, jlen = splt.length - 1; j < jlen; j++) {
              elems.push(splt[j]);
              elems.push(m2[j]);
            }
            elems.push(splt[splt.length - 1]);
            for (var j = 1, jlen = elems.length; j < jlen; j += 2) {
              if (elems[j - 1].trim() && (i2 > 0 || j > 1) && !elems[j - 1].match(CSL.NOTE_FIELD_REGEXP)) {
                break;
              } else {
                elems[j] = "\n" + elems[j].slice(2, -1).trim() + "\n";
              }
            }
            lines[i2] = elems.join("");
          }
        }
        lines = lines.join("\n").split("\n");
        var offset = 0;
        var names = {};
        for (var i2 = 0, ilen = lines.length; i2 < ilen; i2++) {
          var line2 = lines[i2];
          var mm = line2.match(CSL.NOTE_FIELD_REGEXP);
          if (!line2.trim()) {
            continue;
          } else if (!mm) {
            if (i2 === 0) {
              continue;
            } else {
              offset = i2;
              break;
            }
          }
          var key2 = mm[1];
          var val = mm[2].replace(/^\s+/, "").replace(/\s+$/, "");
          if (key2 === "type") {
            Item.type = val;
            lines[i2] = "";
          } else if (CSL.DATE_VARIABLES.indexOf(key2.replace(/^alt-/, "")) > -1) {
            if (!Item[key2] || allowDateOverride) {
              Item[key2] = CSL.DateParser.parseDateToArray(val);
              if (!validFieldsForType || validFieldsForType[key2] && this.isDateString(val)) {
                lines[i2] = "";
              }
            }
          } else if (!Item[key2]) {
            if (CSL.NAME_VARIABLES.indexOf(key2.replace(/^alt-/, "")) > -1) {
              if (!names[key2]) {
                names[key2] = [];
              }
              var lst = val.split(/\s*\|\|\s*/);
              if (lst.length === 1) {
                names[key2].push({ literal: lst[0] });
              } else if (lst.length === 2) {
                var name3 = { family: lst[0], given: lst[1] };
                CSL.parseParticles(name3);
                names[key2].push(name3);
              }
            } else {
              Item[key2] = val;
            }
            if (!validFieldsForType || validFieldsForType[key2]) {
              lines[i2] = "";
            }
          }
        }
        for (var key2 in names) {
          Item[key2] = names[key2];
        }
        if (validFieldsForType) {
          if (lines[offset].trim()) {
            lines[offset] = "\n" + lines[offset];
          }
          for (var i2 = offset - 1; i2 > -1; i2--) {
            if (!lines[i2].trim()) {
              lines = lines.slice(0, i2).concat(lines.slice(i2 + 1));
            }
          }
        }
        Item.note = lines.join("\n").trim();
      },
      checkPrefixSpaceAppend: function(state, prefix2) {
        if (!prefix2) {
          prefix2 = "";
        }
        var sp = "";
        var test_prefix = prefix2.replace(/<[^>]+>/g, "").replace(/["'\u201d\u2019\u00bb\u202f\u00a0 ]+$/g, "");
        var test_char = test_prefix.slice(-1);
        if (test_prefix.match(CSL.ENDSWITH_ROMANESQUE_REGEXP)) {
          sp = " ";
        } else if (CSL.TERMINAL_PUNCTUATION.slice(0, -1).indexOf(test_char) > -1) {
          sp = " ";
        } else if (test_char.match(/[\)\],0-9]/)) {
          sp = " ";
        }
        var prefix2 = (prefix2 + sp).replace(/\s+/g, " ");
        return prefix2;
      },
      checkIgnorePredecessor: function(state, prefix2) {
        var ignorePredecessor = false;
        var test_prefix = prefix2.replace(/<[^>]+>/g, "").replace(/["'\u201d\u2019\u00bb\u202f\u00a0 ]+$/g, "");
        var test_char = test_prefix.slice(-1);
        if (CSL.TERMINAL_PUNCTUATION.slice(0, -1).indexOf(test_char) > -1 && prefix2.trim().indexOf(" ") > -1) {
          state.tmp.term_predecessor = false;
          return true;
        }
        return false;
      },
      checkSuffixSpacePrepend: function(state, suffix) {
        if (!suffix) {
          return "";
        }
        if (suffix.match(CSL.STARTSWITH_ROMANESQUE_REGEXP) || ["[", "("].indexOf(suffix.slice(0, 1)) > -1) {
          suffix = " " + suffix;
        }
        return suffix;
      },
