// ../myst-roles/dist/cite.js
var citeRole = {
  name: "cite",
  alias: [
    "cite:p",
    "cite:t",
    // https://sphinxcontrib-bibtex.readthedocs.io/en/latest/usage.html
    "cite:ps",
    "cite:ts",
    "cite:ct",
    "cite:cts",
    "cite:alp",
    "cite:alps",
    "cite:label",
    "cite:labelpar",
    "cite:year",
    "cite:yearpar",
    "cite:author",
    "cite:authors",
    "cite:authorpar",
    "cite:authorpars",
    "cite:cauthor",
    "cite:cauthors"
    // 'cite:empty',
  ],
  options: { ...commonRoleOptions("cite") },
  body: {
    type: String,
    required: true
  },
  run(data) {
    const content3 = data.body;
    const labels = content3.split(/[,;]/).map((s5) => s5.trim());
    const kind = data.name.startsWith("cite:p") || data.name.includes("par") || data.name.includes("cite:alp") ? "parenthetical" : "narrative";
    const children = labels.map((c) => {
      const groups = /^(?:\{([^{]*)\})?([^{]*)(?:\{([^{]*)\})?$/;
      const [, prefix2, l, suffix] = c.match(groups) ?? ["", "", c];
      const { label, identifier } = normalizeLabel(l) ?? {};
      const cite3 = {
        type: "cite",
        kind,
        label: label ?? l,
        identifier
      };
      if (data.name.startsWith("cite:year")) {
        cite3.partial = "year";
      }
      if (data.name.startsWith("cite:author") || data.name.startsWith("cite:cauthor")) {
        cite3.partial = "author";
      }
      if (prefix2)
        cite3.prefix = prefix2.trim();
      if (suffix)
        cite3.suffix = suffix.trim();
      return cite3;
    });
    if (data.name === "cite" && children.length === 1) {
      addCommonRoleOptions(data, children[0]);
      return children;
    }
    if (data.name.includes("cite:alp")) {
      return children;
    }
    const citeGroup3 = { type: "citeGroup", kind, children };
    addCommonRoleOptions(data, citeGroup3);
    return [citeGroup3];
  }
};

