// ../myst-roles/dist/reference.js
var REF_PATTERN = /^(.+?)<([^<>]+)>$/;
var refRole = {
  name: "ref",
  alias: ["eq", "numref", "prf:ref"],
  body: {
    type: String,
    required: true
  },
  run(data) {
    const body3 = data.body;
    const match3 = REF_PATTERN.exec(body3);
    const [, modified, rawLabel] = match3 ?? [];
    const { label, identifier } = normalizeLabel(rawLabel ?? body3) || {};
    const crossRef = { type: "crossReference", kind: data.name, identifier, label };
    if (modified)
      crossRef.children = [{ type: "text", value: modified.trim() }];
    return [crossRef];
  }
};

// ../myst-roles/dist/doc.js
var REF_PATTERN2 = /^(.+?)<([^<>]+)>$/;
var docRole = {
  name: "doc",
  body: {
    type: String,
    required: true
  },
  run(data, vfile2) {
    const body3 = data.body;
    const match3 = REF_PATTERN2.exec(body3);
    const [, modified, rawLabel] = match3 ?? [];
    const url = rawLabel ?? body3;
    fileWarn(vfile2, "Usage of the {doc} role is not recommended, use a markdown link to the file instead.", {
      source: "role:doc",
      node: data.node,
      note: `For {doc}\`${body3}\` use [${modified || ""}](${url})`,
      ruleId: RuleId.roleBodyCorrect
    });
    const link4 = { type: "link", url };
    if (modified)
      link4.children = [{ type: "text", value: modified.trim() }];
    return [link4];
  }
};

// ../myst-roles/dist/download.js
var REF_PATTERN3 = /^(.+?)<([^<>]+)>$/;
var downloadRole = {
  name: "download",
  body: {
    type: String,
    required: true
  },
  run(data) {
    const body3 = data.body;
    const match3 = REF_PATTERN3.exec(body3);
    const [, modified, rawLabel] = match3 ?? [];
    const url = rawLabel ?? body3;
    const link4 = {
      type: "link",
      url,
      static: true
      // Indicate that this should be treated as a static download
    };
    if (modified)
      link4.children = [{ type: "text", value: modified.trim() }];
    return [link4];
  }
};

// ../myst-roles/dist/indices.js
var REF_PATTERN4 = /^(.+?)<([^<>]+)>$/;
var indexRole = {
  name: "index",
  body: {
    type: String,
    required: true
  },
  run(data, vfile2) {
    const body3 = data.body;
    const match3 = REF_PATTERN4.exec(body3);
    const [, modified, indexString] = match3 ?? [];
    const values = { single: [], pair: [], triple: [], see: [], seealso: [] };
    parseIndexLine(indexString ?? body3, values, vfile2, data.node);
    const entries2 = createIndexEntries(values, vfile2, data.node);
    const output2 = [
      {
        type: "mystTarget",
        indexEntries: entries2
      },
      {
        type: "span",
        children: [
          {
            type: "text",
            value: modified ?? body3
          }
        ]
      }
    ];
    return output2;
  }
};

// ../myst-roles/dist/term.js
var REF_PATTERN5 = /^(.+?)<([^<>]+)>$/;
var termRole = {
  name: "term",
  body: {
    type: String,
    required: true
  },
  run(data, vfile2) {
    const body3 = data.body;
    const match3 = REF_PATTERN5.exec(body3);
    const [, modified, rawLabel] = match3 ?? [];
    const { label, identifier } = normalizeLabel(rawLabel ?? body3) ?? {};
    if (!identifier) {
      fileWarn(vfile2, `Unknown {term} role with body: "${body3}"`, {
        source: "role:term",
        node: data.node,
        ruleId: RuleId.roleBodyCorrect
      });
    }
    const crossRef = {
      type: "crossReference",
      label,
      identifier: `term-${identifier}`,
      children: [{ type: "text", value: modified ? modified.trim() : rawLabel ?? body3 }]
    };
    return [crossRef];
  }
};

// ../myst-roles/dist/si.js
var siRole = {
  name: "si",
  body: {
    type: String,
    required: true
  },
  run(data) {
    const value = data.body;
    const match3 = value.match(/([0-9.,eE-]+)\s?<([\\a-zA-Z\s]+)>/);
    if (!match3) {
      return [{ type: "si", error: true, value }];
    }
    const [, number2, commands] = match3;
    const parsed = [...commands.matchAll(/\\([a-zA-Z]+)/g)];
    const units = parsed.filter((c) => !!c).map(([, c]) => c);
    const translated = units.map((c) => UNITS2[c] ?? c);
    const si = {
      type: "si",
      number: number2,
      unit: translated.join(""),
      units,
      alt: units.join(" "),
      value: `${number2} ${translated.join("")}`
    };
    return [si];
  }
};
